#pragma once
// The two fonts built into the programs, as TrueType bytes: Roboto Medium (the UI font) and JetBrains Mono (code).
// Decoded once from our own OKF1 container (shared/OkfDecode.hpp; data in shared/RobotoFont.h and
// shared/JetBrainsMonoFont.h, generated by scripts/gen_embedded_fonts.py). Header only. Every program reads the fonts
// through here: the engine (okay::EmbeddedUIFontData), the editor, the launcher and the OkayUI script editor.
// (This replaced Dear ImGui's base85 + stb_decompress arrays; tests/test_embedded_font.cpp pins the bytes by SHA-256.)
// Licences of the fonts: docs/status/THIRD_PARTY.md.
#include <cstddef>
#include <cstdint>
#include <vector>

#include "OkfDecode.hpp"
#include "RobotoFont.h"
#include "JetBrainsMonoFont.h"

namespace okf {

namespace detail {
inline std::vector<std::uint8_t> DecodeFont(const char* const* lines, std::size_t lineCount, std::size_t rawBytes) {
    std::vector<std::uint8_t> bytes;
    if (!DecodeLines(lines, lineCount, bytes) || bytes.size() != rawBytes) bytes.clear();
    return bytes;
}
}   // namespace detail

/// Roboto Medium as TrueType bytes; empty only if the embedded data were damaged. The storage lives as long as the
/// program, so a font atlas may keep pointing into it.
inline const std::vector<std::uint8_t>& RobotoMediumTtf() {
    static const std::vector<std::uint8_t> bytes =
        detail::DecodeFont(okf_data::kRobotoMediumOkf, okf_data::kRobotoMediumOkfLines, okf_data::kRobotoMediumOkfRawBytes);
    return bytes;
}

/// JetBrains Mono as TrueType bytes; as RobotoMediumTtf.
inline const std::vector<std::uint8_t>& JetBrainsMonoTtf() {
    static const std::vector<std::uint8_t> bytes =
        detail::DecodeFont(okf_data::kJetBrainsMonoOkf, okf_data::kJetBrainsMonoOkfLines, okf_data::kJetBrainsMonoOkfRawBytes);
    return bytes;
}

/// Add an embedded font to a Dear ImGui style font atlas (Dear ImGui's ImFontAtlas, or OkayUI's compatibility layer):
/// `io.Fonts->AddFontFromMemoryTTF` on the bytes above, with the atlas told NOT to free them (they are static). Null
/// when the bytes are empty or the atlas refuses the font, so callers keep their AddFontDefault fallback.
template <class Atlas, class Config>
auto AddToAtlas(Atlas* atlas, const std::vector<std::uint8_t>& ttf, float px, Config cfg)
    -> decltype(atlas->AddFontFromMemoryTTF(nullptr, 0, px, &cfg)) {
    if (!atlas || ttf.empty()) return nullptr;
    cfg.FontDataOwnedByAtlas = false;
    return atlas->AddFontFromMemoryTTF(const_cast<std::uint8_t*>(ttf.data()), static_cast<int>(ttf.size()), px, &cfg);
}

}   // namespace okf
